SELECT sku_scanned, count(DISTINCT unit_price) AS n_prices, min(unit_price) AS minp, max(unit_price) AS maxp, count(*) AS lines,
       min(bill_ts)::date AS first_day, max(bill_ts)::date AS last_day
FROM store.pos_lines WHERE sku_scanned='ATTA-WW-5KG' GROUP BY sku_scanned;

SELECT count(*) rows, count(DISTINCT bill_id) bills, sum(amount_inr) total,
       min(amount_inr) min_amt, max(amount_inr) max_amt, avg(amount_inr) avg_amt
FROM payments.pos_payments WHERE ts >= '2026-06-01' AND ts < '2026-07-01';

SELECT 'pos_lines' src, min(split_part(bill_id,'-',2))::int lo, max(split_part(bill_id,'-',2))::int hi, count(DISTINCT bill_id) n FROM store.pos_lines
UNION ALL
SELECT 'pos_payments', min(split_part(bill_id,'-',2))::int, max(split_part(bill_id,'-',2))::int, count(DISTINCT bill_id) FROM payments.pos_payments;

WITH pl AS (
  SELECT split_part(bill_id,'-',2)::int seq, count(*) FROM store.pos_lines WHERE bill_ts::date='2026-06-01' GROUP BY 1
), pp AS (
  SELECT split_part(bill_id,'-',2)::int seq, count(*) FROM payments.pos_payments WHERE ts::date='2026-06-01' GROUP BY 1
)
SELECT coalesce(pl.seq,pp.seq) seq, pl.c AS pos_lines_rows, pp.c AS pos_pay_rows
FROM pl FULL JOIN pp USING (seq) ORDER BY seq LIMIT 40;

SELECT sku, gtin, name, pack, case_units, flow, price_inr, cost_inr
FROM store.products
ORDER BY sku;

SELECT sku, min(book_on_hand_close) AS min_b, max(book_on_hand_close) AS max_b,
       count(*) FILTER (WHERE book_on_hand_close <= 0) AS days_le_zero
FROM store.inventory_book GROUP BY sku ORDER BY sku;

SELECT 'daily_sales' t, sku, count(*) n FROM store.daily_sales GROUP BY 1,2
UNION ALL SELECT 'pos_lines', sku_scanned, count(*) FROM store.pos_lines GROUP BY 1,2
ORDER BY 1,2;

SELECT table_schema, table_name FROM information_schema.tables
WHERE table_schema NOT IN ('pg_catalog','information_schema')
ORDER BY 1,2;

SELECT l.bill_date, count(DISTINCT l.bill_id) AS line_bills, count(*) AS lines
FROM (SELECT DISTINCT bill_id, bill_ts::date AS bill_date FROM store.pos_lines) l
GROUP BY 1 ORDER BY 1;

-- Q2: write-off reasons and June counts
SELECT reason, count(*) AS lines, sum(units) AS units, min(date) mn, max(date) mx
FROM store.write_offs GROUP BY reason ORDER BY lines DESC;

-- Q7: stock count triggers and adjustments
SELECT trigger, count(*) n, sum(adjustment) adj, min(count_ts) mn, max(count_ts) mx
FROM store.stock_counts GROUP BY trigger ORDER BY n DESC;
-- warehouse stock_adjustments sample
SELECT * FROM warehouse.stock_adjustments LIMIT 20;

-- Q7: stock count triggers and adjustments
SELECT trigger, count(*) n, sum(adjustment) adj, min(count_ts) mn, max(count_ts) mx
FROM store.stock_counts GROUP BY trigger ORDER BY n DESC;

-- shelf_audits statuses
SELECT status, count(*) n, min(audit_ts) mn, max(audit_ts) mx FROM store.shelf_audits GROUP BY status ORDER BY n DESC;
-- sample shelf audits
SELECT * FROM store.shelf_audits ORDER BY audit_ts LIMIT 30;

-- Q3: till statuses and tenders
SELECT tender, till_status, count(*) n, min(ts) mn, max(ts) mx
FROM payments.pos_payments GROUP BY tender, till_status ORDER BY tender, n DESC;
-- distinct notes
SELECT note, count(*) n FROM payments.pos_payments GROUP BY note ORDER BY n DESC LIMIT 20;

-- tenders
SELECT tender, count(*) n, sum(amount_inr) amt FROM payments.pos_payments GROUP BY tender ORDER BY n DESC;
-- notes
SELECT note, count(*) n FROM payments.pos_payments GROUP BY note ORDER BY n DESC LIMIT 20;

-- psp_upi_report statuses
SELECT status, count(*) n, min(initiated_ts) mn, max(initiated_ts) mx FROM payments.psp_upi_report GROUP BY status ORDER BY n DESC;
-- sample
SELECT * FROM payments.psp_upi_report LIMIT 10;

-- psp statuses
SELECT status, count(*) n FROM payments.psp_upi_report GROUP BY status ORDER BY n DESC;
-- bill_ref populated?
SELECT count(*) total, count(bill_ref) with_bill_ref FROM payments.psp_upi_report;

-- the 48 'failed: no response' rows
SELECT * FROM payments.pos_payments WHERE till_status='failed: no response' ORDER BY ts LIMIT 10;
-- rrn nulls
SELECT count(*) FILTER (WHERE rrn IS NULL) null_rrn, count(*) FILTER (WHERE rrn='') empty_rrn, count(*) total FROM payments.pos_payments;

-- refunds
SELECT * FROM payments.upi_refunds ORDER BY requested_ts;
-- complaints
SELECT * FROM payments.customer_complaints ORDER BY complaint_ts;

-- Re-run with explicit columns to avoid ambiguity
SELECT refund_id, rrn, bill_id, amount_inr, trigger, requested_ts, completed_ts
FROM payments.upi_refunds ORDER BY requested_ts LIMIT 30;

-- complaints with explicit columns
SELECT complaint_ts, kind, amount_inr, bill_id, rrn, resolved_ts, resolution
FROM payments.customer_complaints ORDER BY complaint_ts;

-- Q5 check: do unit prices vary over time (markdowns)? and expired write-offs detail
SELECT sku_scanned sku, unit_price, count(*) n, min(bill_ts)::date mn, max(bill_ts)::date mx
FROM store.pos_lines GROUP BY 1,2 ORDER BY 1,2;

-- Q7: all warehouse stock adjustments + write-offs detail
SELECT * FROM warehouse.stock_adjustments ORDER BY 1;
SELECT * FROM store.write_offs ORDER BY date, sku;

-- Q5: fresh deliveries with use_by for milk/curd/bread
SELECT sku, count(*) deliveries, sum(units) units, min(use_by) min_ub, max(use_by) max_ub,
       min(delivery_ts)::date first_del, max(delivery_ts)::date last_del
FROM store.fresh_deliveries GROUP BY sku ORDER BY sku;
-- sample rows
SELECT * FROM store.fresh_deliveries ORDER BY delivery_ts LIMIT 15;

SELECT note, count(*) AS n, sum(amount_inr) AS amt
FROM payments.pos_payments
GROUP BY note ORDER BY n DESC;

SELECT count(*) AS n, count(DISTINCT rrn) AS distinct_rrn, count(DISTINCT bill_ref) AS distinct_bill_ref,
       min(initiated_ts) AS first_ts, max(initiated_ts) AS last_ts
FROM payments.psp_upi_report;

SELECT table_schema, table_name, column_name, data_type
FROM information_schema.columns
WHERE table_schema='public' ORDER BY table_name, ordinal_position;

SELECT bill_ts, qty, unit_price FROM store.pos_lines
WHERE sku_scanned='ATTA-WW-5KG' AND bill_ts >= '2026-06-08' AND bill_ts < '2026-06-18'
ORDER BY bill_ts;

SELECT grn_id, shipment_id, line, received_ts, asn_sku
FROM store.goods_receipts
WHERE asn_sku='ATTA-WW-5KG' ORDER BY received_ts;

SELECT kind, count(*) AS n, sum(amount_inr) AS amt
FROM payments.customer_complaints
GROUP BY kind ORDER BY amt DESC;
